import requests
import hashlib
from tqdm import tqdm

def get_pubkey(url):
    r = requests.get(url + '/public_key')
    return r.json()

def get_signatures(url, msg, num=10):
    sigs = []
    for _ in range(num):
        resp = requests.get(f"{url}/sign/{msg}")
        js = resp.json()
        sigs.append((js['r'], js['s']))
    return sigs

def sha1int(msg):
    return int.from_bytes(hashlib.sha1(msg.encode('ascii')).digest(), 'big')

def modinv(a, n):
    # Modular inverse using pow for python3+
    return pow(a, -1, n)

def recover_x_from_sig(r, s, k, h, q):
    # From s = k^{-1} (h + x*r) mod q ==> x = (s*k - h)*r^{-1} mod q
    num = (s * k - h) % q
    denom = modinv(r, q)
    return (num * denom) % q

def find_k_and_privkey(p, q, g, y, signatures, msg):
    h = sha1int(msg)
    for idx, (r, s) in enumerate(signatures):
        r = int(r)
        s = int(s)
        for k in tqdm(range(2, 2**16), desc=f'Signature {idx}'):  # 2..65535
            r_candidate = pow(g, k, p) % q
            if r_candidate == r:
                x = recover_x_from_sig(r, s, k, h, q)
                # verify privkey
                if pow(g, x, p) == y:
                    print(f"Recovered k={k} for signature {idx}")
                    print(f"Private key x = {x}")
                    return k, x, idx
    print("No k found in range for any signature.")
    return None, None, None

def main():
    url = 'http://crypto.chal.csaw.io:5000'
    pub = get_pubkey(url)
    p = int(pub['p'])
    q = int(pub['q'])
    g = int(pub['g'])
    y = int(pub['y'])
    msg = 'challenged!'
    signatures = get_signatures(url, msg, 10)
    print(f"First 10 signatures for '{msg}':")
    for sig in signatures:
        print(f"  r={sig[0]}, s={sig[1]}")
    k, x, idx = find_k_and_privkey(p, q, g, y, signatures, msg)
    if x:
        print(f"Recovered private key x: {x}")
    else:
        print("No private key recovered.")

if __name__ == '__main__':
    main()

