import sys
from asn1crypto import algos, core

# DSA signature is an ASN.1 sequence of r, s (both INTEGERs)
def dsa_signature_der(r, s):
    return core.Sequence([core.Integer(r), core.Integer(s)]).dump()

# Inputs: r, s from command line
if __name__ == "__main__":
    r = int(sys.argv[1])
    s = int(sys.argv[2])
    sys.stdout.buffer.write(dsa_signature_der(r, s))

import sys
from asn1crypto import core

class DsaSignature(core.Sequence):
    _fields = [
        ('r', core.Integer),
        ('s', core.Integer)
    ]

def dsa_signature_der(r, s):
    return DsaSignature({'r': r, 's': s}).dump()

if __name__ == "__main__":
    r = int(sys.argv[1])
    s = int(sys.argv[2])
    sys.stdout.buffer.write(dsa_signature_der(r, s))

